1	// 故障注入测试辅助（仅测试代码使用）。
2	//
3	// C++ 回归套件在本进程内直接调用 branchaudit_core 的文件计算接口，因此
4	// “打不开 / 中途读出错”需要故障注入共享库（tests/fault_inject.c）随本
5	// 进程一起预载：
6	//
7	//   * ctest 已通过 ENVIRONMENT 设置 LD_PRELOAD，正常运行时无需任何动作；
8	//   * 直接手工执行测试二进制时，ensure_fault_preloaded() 会在发现注入库
9	//     未加载时，带上 LD_PRELOAD 重新执行自身一次；
10	//   * 具体失败用例用 FaultTrigger 在作用域内设置精确路径触发变量，退出
11	//     作用域立即清除；其他路径与其余用例不受影响。
12	
13	#pragma once
14	
15	#include <cstdlib>
16	#include <cstring>
17	#include <fstream>
18	#include <string>
19	#include <unistd.h>
20	
21	namespace fault_test {
22	
23	// 由 CMake 以编译定义注入故障库绝对路径；直接运行且无定义时退回环境变量。
24	inline const char *fault_lib_path() {
25	#ifdef BRANCHAUDIT_FAULT_LIB
26	    return BRANCHAUDIT_FAULT_LIB;
27	#else
28	    return std::getenv("BRANCHAUDIT_FAULT_LIB");
29	#endif
30	}
31	
32	// /proc/self/maps 中是否已映射故障注入库。
33	inline bool fault_lib_loaded() {
34	    const char *lib = fault_lib_path();
35	    if (!lib) return false;
36	    const char *slash = std::strrchr(lib, '/');
37	    const std::string base = slash ? std::string(slash + 1) : std::string(lib);
38	    std::ifstream maps("/proc/self/maps");
39	    std::string line;
40	    while (std::getline(maps, line)) {
41	        if (line.find(base) != std::string::npos) return true;
42	    }
43	    return false;
44	}
45	
46	// 未加载故障库时带 LD_PRELOAD 重新执行自身；已加载则直接返回。
47	inline void ensure_fault_preloaded(int argc, char **argv) {
48	    if (fault_lib_loaded()) return;
49	    const char *lib = fault_lib_path();
50	    // 已经重入过一次仍未加载（如库路径无效）：放弃注入，避免无限 re-exec。
51	    if (!lib || getenv("BRANCHAUDIT_FAULT_REEXECED")) return;
52	
53	    std::string preload = lib;
54	    if (const char *existing = std::getenv("LD_PRELOAD")) {
55	        if (*existing) {
56	            preload.push_back(':');
57	            preload += existing;
58	        }
59	    }
60	    setenv("LD_PRELOAD", preload.c_str(), 1);
61	    setenv("BRANCHAUDIT_FAULT_REEXECED", "1", 1);
62	
63	    std::string exe;
64	    {
65	        char buf[4096];
66	        ssize_t n = readlink("/proc/self/exe", buf, sizeof buf - 1);
67	        if (n <= 0) return;
68	        buf[n] = '\0';
69	        exe = buf;
70	    }
71	    // argv[argc] 按标准即为空指针，execv 直接复用。
72	    execv(exe.c_str(), argv);
73	    // execv 失败则继续原进程；失败用例会如实报告未触发。
74	}
75	
76	// 作用域内设置故障触发环境变量，退出作用域清除。
77	class FaultTrigger {
78	public:
79	    FaultTrigger(const char *variable, std::string value) : variable_(variable) {
80	        setenv(variable_, value.c_str(), 1);
81	    }
82	    ~FaultTrigger() { unsetenv(variable_); }
83	
84	    FaultTrigger(const FaultTrigger &) = delete;
85	    FaultTrigger &operator=(const FaultTrigger &) = delete;
86	
87	private:
88	    const char *variable_;
89	};
90	
91	}  // namespace fault_test
