1	/*
2	 * 测试专用故障注入共享库（非生产代码），仅经 LD_PRELOAD 加载。
3	 *
4	 * 目的：让回归测试在自身安排的条件下，稳定触发两类真实的文件访问
5	 * 错误，而不依赖碰巧出现的磁盘故障或人工干预：
6	 *
7	 *   1. 文件确实存在却打不开：
8	 *      BRANCHAUDIT_TEST_OPEN_FAIL=<path>
9	 *      对该路径的 fopen/open 系列调用直接失败，errno = EACCES。
10	 *
11	 *   2. 文件已打开、取得部分内容后继续读取时出错：
12	 *      BRANCHAUDIT_TEST_READ_FAIL=<path>[:<bytes>]
13	 *      该路径可以正常打开；读取照常交付前 <bytes> 个字节（默认 40），
14	 *      此后对该文件描述符的下一次 read 失败，errno = EIO。
15	 *
16	 * 空文件在第二种注入下仍然是正常读完成功：首次 read 即返回 0（一个
17	 * 字节都没有读到）时透传 EOF，不把“没有读到内容”当作错误。夹具文件
18	 * 应大于 <bytes>，以保证“取得部分内容后继续读取”确实发生。
19	 *
20	 * 不设置上述环境变量时，本库对程序行为没有任何影响：所有调用都透传
21	 * 给 libc。错误发生在与生产代码完全相同的 libc 文件访问接口上，因此
22	 * 被测程序必须真正完成“定位 -> 打开 -> 流式读取 -> 错误传播”的整条
23	 * 路径，不可能用一个写死错误文字的返回值蒙混过关。
24	 *
25	 * 实现为介入公共 libc 符号（fopen/fopen64、open/openat 系列、read、
26	 * __read_chk、close）。不同 glibc 的 std::basic_filebuf 可能经由
27	 * fopen 或 open 系列打开、经由 read 或 __read_chk 读取，因此这些入口
28	 * 一并覆盖；read 侧另用 /proc/self/fd 比对目标路径作为兜底，使任何
29	 * 打开入口下的故障文件描述符都能被识别。
30	 */
31	
32	#define _GNU_SOURCE
33	
34	#include <dlfcn.h>
35	#include <errno.h>
36	#include <fcntl.h>
37	#include <stdarg.h>
38	#include <stdio.h>
39	#include <stdlib.h>
40	#include <string.h>
41	#include <sys/types.h>
42	#include <unistd.h>
43	
44	#define FD_CAP 4096
45	
46	/* fd 分类：0=未知（首次见到），1=读取故障文件，-1=与故障无关。 */
47	static int g_state[FD_CAP];
48	/* g_state==1 的 fd：已交付字节数与开始报错的阈值。 */
49	static long g_delivered[FD_CAP];
50	static long g_fail_after[FD_CAP];
51	
52	static FILE *(*g_real_fopen)(const char *, const char *);
53	static FILE *(*g_real_fopen64)(const char *, const char *);
54	static int (*g_real_open)(const char *, int, mode_t);
55	static int (*g_real_openat)(int, const char *, int, mode_t);
56	static ssize_t (*g_real_read)(int, void *, size_t);
57	static int (*g_real_close)(int);
58	
59	/* 提前在构造器中解析真实符号：read 在动态链接器装载阶段就可能被调用，
60	 * 惰性 dlsym 若内部再调用 read 会递归。 */
61	__attribute__((constructor)) static void resolve_real_symbols(void) {
62	    g_real_fopen = dlsym(RTLD_NEXT, "fopen");
63	    g_real_fopen64 = dlsym(RTLD_NEXT, "fopen64");
64	    g_real_open = dlsym(RTLD_NEXT, "open");
65	    g_real_openat = dlsym(RTLD_NEXT, "openat");
66	    g_real_read = dlsym(RTLD_NEXT, "read");
67	    g_real_close = dlsym(RTLD_NEXT, "close");
68	}
69	
70	static const char *open_fail_target(void) {
71	    return getenv("BRANCHAUDIT_TEST_OPEN_FAIL");
72	}
73	
74	/* 返回读取故障目标路径，并通过 *bytes_out 回传部分交付阈值。 */
75	static const char *read_fail_target(long *bytes_out) {
76	    const char *spec = getenv("BRANCHAUDIT_TEST_READ_FAIL");
77	    long n = 40;
78	    if (spec) {
79	        const char *colon = strchr(spec, ':');
80	        if (colon) {
81	            long parsed = strtol(colon + 1, NULL, 10);
82	            if (parsed > 0) n = parsed;
83	        }
84	    }
85	    *bytes_out = n;
86	    return spec;
87	}
88	
89	static int path_matches(const char *path, const char *target) {
90	    if (!path || !target) return 0;
91	    /* 目标规格里冒号之后是阈值，比较时只取路径部分。 */
92	    size_t len = strcspn(target, ":");
93	    return strlen(path) == len && strncmp(path, target, len) == 0;
94	}
95	
96	/* 通过 /proc/self/fd 判定打开着的 fd 是否指向目标路径。 */
97	static int fd_points_at(int fd, const char *target) {
98	    if (fd < 0 || fd >= FD_CAP || !target) return 0;
99	    char proc[64];
100	    snprintf(proc, sizeof proc, "/proc/self/fd/%d", fd);
101	    char link[4096];
102	    ssize_t n = readlink(proc, link, sizeof link - 1);
103	    if (n <= 0) return 0;
104	    link[n] = '\0';
105	    size_t len = strcspn(target, ":");
106	    return (size_t)n == len && strncmp(link, target, len) == 0;
107	}
108	
109	static void classify_fd(int fd) {
110	    if (fd < 0 || fd >= FD_CAP || g_state[fd] != 0) return;
111	    long threshold;
112	    const char *target = read_fail_target(&threshold);
113	    if (target && fd_points_at(fd, target)) {
114	        g_state[fd] = 1;
115	        g_delivered[fd] = 0;
116	        g_fail_after[fd] = threshold;
117	    } else {
118	        g_state[fd] = -1;
119	    }
120	}
121	
122	/* fd -> 文件的关联在 open 成功时才建立。无论旧 fd 是如何关闭的（可能
123	 * 经过未介入的内部 close，留下过期缓存），这里都先清掉该 fd 的旧状态再
124	 * 重新分类，避免复用的 fd 沿用启动期（如读取 locale/ELF 时）的结论。 */
125	static void reclassify_fd(int fd) {
126	    if (fd < 0 || fd >= FD_CAP) return;
127	    g_state[fd] = 0;
128	    g_delivered[fd] = 0;
129	    g_fail_after[fd] = 0;
130	    classify_fd(fd);
131	}
132	
133	/* ---- 打开失败：fopen 系列 ----------------------------------------------- */
134	
135	FILE *fopen(const char *path, const char *mode) {
136	    if (path_matches(path, open_fail_target())) {
137	        errno = EACCES;
138	        return NULL;
139	    }
140	    FILE *f = g_real_fopen(path, mode);
141	    if (f) reclassify_fd(fileno(f));
142	    return f;
143	}
144	
145	FILE *fopen64(const char *path, const char *mode) {
146	    if (path_matches(path, open_fail_target())) {
147	        errno = EACCES;
148	        return NULL;
149	    }
150	    FILE *f = g_real_fopen64(path, mode);
151	    if (f) reclassify_fd(fileno(f));
152	    return f;
153	}
154	
155	/* ---- 打开失败：open/openat 系列（含 FORTIFY 变体） ---------------------- */
156	/*
157	 * 无版本号的介入定义在部分 glibc 上不会接管带版本号的 __*_2 引用，但对
158	 * 经由普通 open/openat 打开文件的构建同样有效；两条打开路径都覆盖以提高
159	 * 可移植性，fopen 系列在常见 glibc 构建上负责实际接管。
160	 */
161	
162	static int intercept_open(const char *path, int flags, int has_mode,
163	                          mode_t mode) {
164	    if (path_matches(path, open_fail_target())) {
165	        errno = EACCES;
166	        return -1;
167	    }
168	    int fd = g_real_open(path, flags, has_mode ? mode : 0);
169	    reclassify_fd(fd);
170	    return fd;
171	}
172	
173	static int intercept_openat(int dirfd, const char *path, int flags,
174	                            int has_mode, mode_t mode) {
175	    if (path_matches(path, open_fail_target())) {
176	        errno = EACCES;
177	        return -1;
178	    }
179	    int fd = g_real_openat(dirfd, path, flags, has_mode ? mode : 0);
180	    reclassify_fd(fd);
181	    return fd;
182	}
183	
184	int open(const char *path, int flags, ...) {
185	    mode_t mode = 0;
186	    if (flags & O_CREAT) {
187	        va_list ap;
188	        va_start(ap, flags);
189	        mode = va_arg(ap, mode_t);
190	        va_end(ap);
191	    }
192	    return intercept_open(path, flags, flags & O_CREAT, mode);
193	}
194	
195	int open64(const char *path, int flags, ...) {
196	    mode_t mode = 0;
197	    if (flags & O_CREAT) {
198	        va_list ap;
199	        va_start(ap, flags);
200	        mode = va_arg(ap, mode_t);
201	        va_end(ap);
202	    }
203	    return intercept_open(path, flags, flags & O_CREAT, mode);
204	}
205	
206	int openat(int dirfd, const char *path, int flags, ...) {
207	    mode_t mode = 0;
208	    if (flags & O_CREAT) {
209	        va_list ap;
210	        va_start(ap, flags);
211	        mode = va_arg(ap, mode_t);
212	        va_end(ap);
213	    }
214	    return intercept_openat(dirfd, path, flags, flags & O_CREAT, mode);
215	}
216	
217	int openat64(int dirfd, const char *path, int flags, ...) {
218	    mode_t mode = 0;
219	    if (flags & O_CREAT) {
220	        va_list ap;
221	        va_start(ap, flags);
222	        mode = va_arg(ap, mode_t);
223	        va_end(ap);
224	    }
225	    return intercept_openat(dirfd, path, flags, flags & O_CREAT, mode);
226	}
227	
228	int __open_2(const char *path, int flags) {
229	    return intercept_open(path, flags, 0, 0);
230	}
231	
232	int __open64_2(const char *path, int flags) {
233	    return intercept_open(path, flags, 0, 0);
234	}
235	
236	int __openat_2(int dirfd, const char *path, int flags) {
237	    return intercept_openat(dirfd, path, flags, 0, 0);
238	}
239	
240	int __openat64_2(int dirfd, const char *path, int flags) {
241	    return intercept_openat(dirfd, path, flags, 0, 0);
242	}
243	
244	/* ---- 部分内容后读取失败 -------------------------------------------------- */
245	
246	static ssize_t fault_read(int fd, void *buf, size_t n) {
247	    if (fd < 0 || fd >= FD_CAP) return g_real_read(fd, buf, n);
248	
249	    if (g_state[fd] == 0) classify_fd(fd);
250	
251	    if (g_state[fd] != 1) return g_real_read(fd, buf, n);
252	
253	    const long threshold = g_fail_after[fd];
254	    const long delivered = g_delivered[fd];
255	    if (delivered > 0 && delivered >= threshold) {
256	        /* 已经取得部分内容，继续读取即报错——不能当作正常到达文件末尾。 */
257	        errno = EIO;
258	        return -1;
259	    }
260	
261	    /* 把本次读取限制在阈值之内，确保错误发生在“部分内容之后”的下一次
262	     * 读取上，而不是等文件被一次性读完。空文件首次 real_read 返回 0，
263	     * 原样透传为正常 EOF。 */
264	    size_t want = n;
265	    const long remain = threshold - delivered;
266	    if (remain > 0 && (long)n > remain) want = (size_t)remain;
267	
268	    ssize_t r = g_real_read(fd, buf, want);
269	    if (r > 0) g_delivered[fd] += r;
270	    return r;
271	}
272	
273	ssize_t read(int fd, void *buf, size_t n) {
274	    return fault_read(fd, buf, n);
275	}
276	
277	ssize_t __read_chk(int fd, void *buf, size_t n, size_t buflen) {
278	    if (n > buflen) abort();  // 与 glibc __chk_fail 相同的 fortify 失败语义
279	    return fault_read(fd, buf, n);
280	}
281	
282	/* ---- 关闭时清理 fd 状态 -------------------------------------------------- */
283	
284	int close(int fd) {
285	    if (fd >= 0 && fd < FD_CAP) {
286	        g_state[fd] = 0;
287	        g_delivered[fd] = 0;
288	        g_fail_after[fd] = 0;
289	    }
290	    return g_real_close(fd);
291	}
292

