52	// 按给定偏移分段提交（偏移为相对起点的累计切分点，0 与 data.size() 可省略）。
53	std::string hash_parts(const std::vector<unsigned char>& data,
54	                       const std::vector<std::size_t>& cuts) {
55	    branchaudit::Sha256 sha;
56	    std::size_t prev = 0;
57	    for (std::size_t cut : cuts) {
58	        sha.update(data.data() + prev, cut - prev);
59	        prev = cut;
60	    }
61	    sha.update(data.data() + prev, data.size() - prev);
62	    return hex_of(sha.final());
63	}
