172	void test_incremental_splits() {
173	    const std::size_t sizes[] = {0, 1, 2, 3, 55, 56, 63, 64, 65, 66,
174	                                 127, 128, 129, 200, 255, 256, 257};
175	    for (std::size_t n : sizes) {
176	        const std::vector<unsigned char> data = pattern(n);
177	        const std::string whole = hash_whole(data);
178	        // 每个切分点都试：含空段、恰好在 64 字节边界上、把边界两侧拆开。
179	        for (std::size_t cut = 0; cut <= n; ++cut) {
180	            check(hash_parts(data, {cut}) == whole,
181	                  "2-way split n=" + std::to_string(n) + " cut=" + std::to_string(cut));
182	        }
183	    }
184	
185	    // 较大输入上围绕分组边界的三分段组合。
186	    {
187	        const std::size_t n = 200;
188	        const std::vector<unsigned char> data = pattern(n);
189	        const std::string whole = hash_whole(data);
190	        const std::size_t points[] = {0, 1, 7, 55, 56, 63, 64, 65,
191	                                      127, 128, 129, 135, 199, 200};
192	        for (std::size_t c1 : points) {
193	            for (std::size_t c2 : points) {
194	                if (c1 > c2) continue;
195	                check(hash_parts(data, {c1, c2}) == whole,
196	                      "3-way split 200 @ " + std::to_string(c1) + "," +
197	                      std::to_string(c2));
198	            }
199	        }
200	    }
201	
202	    // 手工构造的对抗性分段：边界两侧逐字节拆开，缓冲区跨多次 update 填满。
203	    {
204	        const std::vector<unsigned char> data = pattern(300);
205	        const std::string whole = hash_whole(data);
206	        const std::size_t plans[][5] = {
207	            {63, 64, 64, 65, 44},   // 300 = 63+64+64+65+44
208	            {1, 64, 64, 64, 107},   // 300 = 1+64*3+107
209	            {56, 8, 56, 8, 172},
210	            {55, 1, 55, 1, 188},
211	        };
212	        for (const auto& plan : plans) {
213	            branchaudit::Sha256 sha;
214	            std::size_t off = 0;
215	            for (std::size_t len : plan) {
216	                sha.update(data.data() + off, len);
217	                off += len;
218	            }
219	            check(off == 300 && hex_of(sha.final()) == whole,
220	                  "adversarial segmented update");
221	        }
222	    }
