242	void write_file(const fs::path& p, const std::vector<unsigned char>& bytes) {
243	    fs::create_directories(p.parent_path());
244	    std::ofstream out(p, std::ios::binary | std::ios::trunc);
245	    out.write(reinterpret_cast<const char*>(bytes.data()),
246	              static_cast<std::streamsize>(bytes.size()));
247	    check(static_cast<bool>(out), std::string("write fixture ") + p.string());
248	}
