250	// 调用库接口期间截获标准输出/错误：库只返回结果，不自行打印。
251	std::pair<std::string, std::string> silent_file_hash(const fs::path& p,
252	                                                     branchaudit::FileHashResult* out) {
253	    std::stringstream cap_out, cap_err;
254	    auto* old_out = std::cout.rdbuf(cap_out.rdbuf());
255	    auto* old_err = std::cerr.rdbuf(cap_err.rdbuf());
256	    *out = branchaudit::sha256_file(p);
257	    std::cout.rdbuf(old_out);
258	    std::cerr.rdbuf(old_err);
259	    return {cap_out.str(), cap_err.str()};
260	}
