262	void test_file_hashing() {
263	    TempArea tmp("file");
264	
265	    struct Case {
266	        std::string name;
267	        std::vector<unsigned char> bytes;
268	        std::string expected;  // sha256sum / OpenSSL 独立结果
269	    };
270	    const std::vector<unsigned char> binary = {'a', 0x00, 'b', 0xff, ' ',
271	                                               'c', '\n', 'd'};
272	    std::vector<Case> cases = {
273	        {"empty.bin", {},
274	         "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855"},
275	        {"text.txt",
276	         {'h', 'e', 'l', 'l', 'o', ' ', 'w', 'o', 'r', 'l', 'd', '\n'},
277	         ""},  // 下方用 sha256sum 风格常量填充
278	        {"binary.bin", binary,
279	         "ae37f71921db5e6d58be22370d3f0cc73cd4fa8bcc327dccd8b881094bc03d7c"},
280	        {"bound55.bin", fill_a(55),
281	         "9f4390f8d30c2dd92ec9f095b65e2b9ae9b0a925a5258e241c9f1e910f734318"},
282	        {"bound56.bin", fill_a(56),
283	         "b35439a4ac6f0948b6d6f9e3c6af0f5f590ce20f1bde7090ef7970686ec6738a"},
284	        {"bound63.bin", fill_a(63),
285	         "7d3e74a05d7db15bce4ad9ec0658ea98e3f06eeecf16b4c6fff2da457ddc2f34"},
286	        {"bound64.bin", fill_a(64),
287	         "ffe054fe7ae0cb6dc65c3af9b61d5209f439851db43d0ba5997337df154668eb"},
288	        {"bound65.bin", fill_a(65),
289	         "635361c48bb9eab14198e76ea8ab7f1a41685d6ad62aa9146d301d4f17eb0ae0"},
290	        // 超过 64KiB 且不是 64KiB 整数倍：尾部不能被遗漏。
291	        {"large65537.bin", fill_a(64 * 1024 + 1),
292	         "008ffc88d3c96a9f307524eb361e47c5222a887fc45fa0c1fb8d429c5c23b430"},
293	        {"large131073.bin", fill_a(128 * 1024 + 1),
294	         "7e009ea4ef882e385b3c0bcbbfa8d009bb0a633bdd764415c09182ee0e75da73"},
295	        {"large200000.bin", fill_a(200000),
296	         "2287d207f24a941ff3b56c04c8a25ad56b63e3023207b3bb5b4ac0c9869d74be"},
297	    };
298	    // "hello world\n" 的独立标准结果。
299	    cases[1].expected =
300	        "a948904f2f0f479b8f8197694b30184b0d2ed1c1cd2a1ec0fb85d299a192a447";
301	
302	    std::string same_bytes_digest;
303	    for (std::size_t i = 0; i < cases.size(); ++i) {
304	        const auto& c = cases[i];
305	        const fs::path p = tmp.root / c.name;
306	        write_file(p, c.bytes);
307	
308	        branchaudit::FileHashResult r;
309	        auto [cout_text, cerr_text] = silent_file_hash(p, &r);
310	        check(r.ok(), std::string("file hash ok: ") + c.name);
311	        check(cout_text.empty() && cerr_text.empty(),
312	              std::string("library prints nothing: ") + c.name);
313	        check(r.digest.size() == 32, std::string("digest is 32 bytes: ") + c.name);
314	        check(hex_of(r.digest) == c.expected,
315	              std::string("file digest matches independent standard: ") + c.name);
316	        check(hex_of(r.digest) == hash_whole(c.bytes),
317	              std::string("file digest matches incremental API: ") + c.name);
318	        if (c.name == "binary.bin") same_bytes_digest = hex_of(r.digest);
319	    }
320	
321	    // 同样字节放在不同文件名/目录下必须同一摘要，路径文字不混入。
322	    const std::vector<unsigned char>& shared_bytes = cases[2].bytes;
323	    const fs::path alt_paths[] = {
324	        tmp.root / "copy.bin",
325	        tmp.root / "sub dir" / "another name.dat",
326	        tmp.root / "目录 一" / "文件 二.bin",
327	    };
328	    for (const auto& p : alt_paths) {
329	        write_file(p, shared_bytes);
330	        branchaudit::FileHashResult r;
331	        auto captured = silent_file_hash(p, &r);
332	        check(r.ok() && hex_of(r.digest) == same_bytes_digest,
333	              std::string("same bytes same digest regardless of path: ") + p.string());
334	        check(captured.first.empty() && captured.second.empty(),
335	              std::string("no printing for path: ") + p.string());
336	    }
337	
338	    // 路径含空格或中文：完整路径必须准确定位。
339	    const fs::path spaced = tmp.root / "spa ce dir" / "na me.bin";
340	    write_file(spaced, binary);
341	    {
342	        branchaudit::FileHashResult r;
343	        auto captured = silent_file_hash(spaced, &r);
344	        check(r.ok() && hex_of(r.digest) == same_bytes_digest,
345	              "path with spaces locates file");
346	        check(captured.first.empty() && captured.second.empty(),
347	              "path with spaces: no printing");
348	    }
349	    const fs::path chinese =
350	        tmp.root / "中文目录" / "摘要文件 数据.bin";
351	    write_file(chinese, fill_a(65));
352	    {
353	        branchaudit::FileHashResult r;
354	        auto captured = silent_file_hash(chinese, &r);
355	        check(r.ok() &&
356	                  hex_of(r.digest) ==
357	                      "635361c48bb9eab14198e76ea8ab7f1a41685d6ad62aa9146d301d4f17eb0ae0",
358	              "Chinese path locates file; path text not mixed into digest");
359	        check(captured.first.empty() && captured.second.empty(),
360	              "Chinese path: no printing");
361	    }
362	
363	    // 相对路径同样按完整路径定位。
364	    const fs::path rel_dir = tmp.root / "rel 目录";
365	    fs::create_directories(rel_dir);
366	    const fs::path rel_name = "r.bin";
367	    write_file(rel_dir / rel_name, binary);
368	    const fs::path old_cwd = fs::current_path();
369	    fs::current_path(rel_dir);
370	    branchaudit::FileHashResult rel_result;
371	    auto rel_captured = silent_file_hash(rel_name, &rel_result);
372	    fs::current_path(old_cwd);
373	    check(rel_result.ok() && hex_of(rel_result.digest) == same_bytes_digest,
374	          "relative path resolved from current directory");
375	    check(rel_captured.first.empty() && rel_captured.second.empty(),
376	          "relative path: no printing");
