381	void test_file_failures() {
382	    TempArea tmp("fail");
383	
384	    // 路径不存在
385	    const fs::path missing = tmp.root / "does not exist 缺失.bin";
386	    {
387	        branchaudit::FileHashResult r;
388	        auto captured = silent_file_hash(missing, &r);
389	        check(!r.ok(), "nonexistent path: failure result");
390	        check(!r.error.empty(), "nonexistent path: error states reason");
391	        check(r.error.find(missing.string()) != std::string::npos,
392	              "nonexistent path: error names failed path");
393	        check(r.error.size() > missing.string().size() + 2,
394	              "nonexistent path: error gives reason beyond the path");
395	        check(captured.first.empty() && captured.second.empty(),
396	              "nonexistent path: library does not print");
397	    }
398	
399	    // 路径指向目录
400	    const fs::path dir = tmp.root / "a dir 目录";
401	    fs::create_directories(dir);
402	    {
403	        branchaudit::FileHashResult r;
404	        auto captured = silent_file_hash(dir, &r);
405	        check(!r.ok(), "directory path: failure result");
406	        check(!r.error.empty(), "directory path: error states reason");
407	        check(r.error.find(dir.string()) != std::string::npos,
408	              "directory path: error names failed path");
409	        check(r.error.find("directory") != std::string::npos,
410	              "directory path: error explains it is a directory");
411	        check(captured.first.empty() && captured.second.empty(),
412	              "directory path: library does not print");
