416	// ---- 文件失败行为：存在却打不开 / 部分读取后继续读出错 --------------------
417	//
418	// 这两类错误无法用“缺失路径/目录”夹具制造：文件真实存在、打开成功，
419	// 错误分别发生在 open 与后续 read 上。通过随测试预载的故障注入库在
420	// libc 文件访问接口处确定性触发（见 tests/fault_inject.c），因此被测
421	// 代码走的是与生产完全相同的“定位 -> 打开 -> 流式读取 -> 错误传播”
422	// 路径，而不是构造一个带错误文字的返回值。
423	
424	void test_file_io_failures() {
425	    TempArea tmp("iofail");
426	
427	    // 打开失败与读取失败共用的夹具：文件确定存在、内容确定。
428	    const fs::path existing = tmp.root / "present 存在.bin";
429	    constexpr long kPartial = 40;
430	    const std::vector<unsigned char> bytes = pattern(200);
431	    write_file(existing, bytes);
432	
433	    // 同一文件不注入时必须成功，证明失败确由文件访问错误引起，而不是
434	    // 针对该路径写死的错误结果。
435	    {
436	        branchaudit::FileHashResult r;
437	        auto captured = silent_file_hash(existing, &r);
438	        check(r.ok() && hex_of(r.digest) == hash_whole(bytes),
439	              "iofail fixture: succeeds without injected fault");
440	        check(captured.first.empty() && captured.second.empty(),
441	              "iofail fixture: library stays silent on success");
442	    }
443	
444	    // ---- 文件确实存在却不能打开 ----------------------------------------
445	    {
446	        fault_test::FaultTrigger trigger(
447	            "BRANCHAUDIT_TEST_OPEN_FAIL", existing.string());
448	        branchaudit::FileHashResult r;
449	        auto captured = silent_file_hash(existing, &r);
450	        check(!r.ok(), "existing-but-unopenable: failure result");
451	        check(r.error.find(existing.string()) != std::string::npos,
452	              "open failure: error names the failed path");
453	        check(r.error.find("ermission") != std::string::npos ||
454	                  r.error.find("denied") != std::string::npos ||
455	                  r.error.find("cces") != std::string::npos,
456	              "open failure: error states an open/permission reason");
457	        check(r.error.size() > existing.string().size() + 2,
458	              "open failure: error gives reason beyond the path");
459	        check(captured.first.empty() && captured.second.empty(),
460	              "open failure: library only returns result, prints nothing");
461	    }
462	    // 触发变量离开作用域后，同一文件恢复成功。
463	    {
464	        branchaudit::FileHashResult r;
465	        silent_file_hash(existing, &r);
466	        check(r.ok(), "open trigger scoped: later access succeeds again");
467	    }
468	
469	    // ---- 文件已打开、取得部分内容后继续读取时出错 ----------------------
470	    {
471	        fault_test::FaultTrigger trigger(
472	            "BRANCHAUDIT_TEST_READ_FAIL",
473	            existing.string() + ":" + std::to_string(kPartial));
474	        branchaudit::FileHashResult r;
475	        auto captured = silent_file_hash(existing, &r);
476	        check(!r.ok(), "read error after partial content: failure result");
477	        check(r.error.find(existing.string()) != std::string::npos,
478	              "read failure: error names the failed path");
479	        check(r.error.find("read") != std::string::npos,
480	              "read failure: error states it is a read failure (not EOF)");
481	        check(r.error.size() > existing.string().size() + 2,
482	              "read failure: error gives reason beyond the path");
483	        check(captured.first.empty() && captured.second.empty(),
484	              "read failure: library only returns result, prints nothing");
485	
486	        // 已读到的部分内容绝不能成为成功摘要：既不是完整文件摘要，也不
487	        // 是前 kPartial 字节的摘要。
488	        const std::string got = hex_of(r.digest);
489	        check(got != hash_whole(bytes),
490	              "read failure: digest is not the whole-file summary");
491	        check(got != hash_whole(std::vector<unsigned char>(
492	                      bytes.begin(), bytes.begin() + kPartial)),
493	              "read failure: already-read partial content is not a success digest");
494	    }
495	
496	    // ---- 空文件正常读完仍然成功：没有读到内容不等于读错误 --------------
497	    const fs::path empty = tmp.root / "empty 空.bin";
498	    write_file(empty, {});
499	    {
500	        fault_test::FaultTrigger trigger(
501	            "BRANCHAUDIT_TEST_READ_FAIL",
502	            empty.string() + ":" + std::to_string(kPartial));
503	        branchaudit::FileHashResult r;
504	        auto captured = silent_file_hash(empty, &r);
505	        check(r.ok(), "empty file read to completion: still success under read-fault arm");
506	        check(hex_of(r.digest) ==
507	                  "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855",
508	              "empty file still yields SHA-256 of empty sequence");
509	        check(captured.first.empty() && captured.second.empty(),
510	              "empty file: library stays silent");
511	    }
512	
513	    // ---- 触发只作用于指定路径：其他文件不受影响 ------------------------
514	    const fs::path other = tmp.root / "other.bin";
515	    write_file(other, bytes);
516	    {
517	        fault_test::FaultTrigger trigger(
518	            "BRANCHAUDIT_TEST_READ_FAIL",
519	            existing.string() + ":" + std::to_string(kPartial));
520	        branchaudit::FileHashResult r;
521	        silent_file_hash(other, &r);
522	        check(r.ok() && hex_of(r.digest) == hash_whole(bytes),
523	              "fault is path-scoped: unrelated file still hashes correctly");
524	    }
525	}
526	
527	// ---- to_hex 格式 ----------------------------------------------------------
528	
529	void test_hex_format() {
530	    branchaudit::Sha256 sha;
531	    const auto digest = sha.final();  // 空输入摘要
532	    const std::string hex = branchaudit::to_hex(digest);
533	    check(hex.size() == 64, "to_hex returns 64 characters");
534	    bool lowercase = true;
535	    for (char ch : hex) {
536	        const bool ok_digit = (ch >= '0' && ch <= '9') || (ch >= 'a' && ch <= 'f');
537	        if (!ok_digit) lowercase = false;
538	    }
539	    check(lowercase, "to_hex is lowercase hexadecimal");
540	    check(hex == "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855",
541	          "to_hex of empty digest matches standard");
542	}
543	
544	}  // namespace
545	
546	int main(int argc, char** argv) {
547	    fault_test::ensure_fault_preloaded(argc, argv);
548	
549	    test_standard_vectors();
550	    test_byte_semantics();
551	    test_boundary_lengths();
552	    test_incremental_splits();
553	    test_file_hashing();
554	    test_file_failures();
555	    test_file_io_failures();
556	    test_hex_format();
557	
558	    if (g_failures == 0) {
559	        std::cout << "all " << g_checks << " sha256 regression checks passed\n";
560	        return 0;
561	    }
562	    std::cerr << g_failures << " of " << g_checks << " checks failed\n";
563	    return 1;
564	}
