95	// 调用库接口期间截获标准输出/错误：库只返回结果，不自行打印、不退出。
96	std::pair<std::string, std::string> silent_merkle(
97	        const std::vector<fs::path>& paths, branchaudit::FileHashResult* out) {
98	    std::stringstream cap_out, cap_err;
99	    auto* old_out = std::cout.rdbuf(cap_out.rdbuf());
100	    auto* old_err = std::cerr.rdbuf(cap_err.rdbuf());
101	    *out = branchaudit::merkle_root_files(paths);
102	    std::cout.rdbuf(old_out);
103	    std::cerr.rdbuf(old_err);
104	    return {cap_out.str(), cap_err.str()};
105	}
