133	              "022a6979e6dab7aa5ae4c3e5e45f7e977112a7e63593820dbec1ec738a24f93c",
134	          "leaf('a') = SHA-256(0x00 || 'a')");
135	    check(hex_of(leaf_bytes(bytes_of("abc"))) ==
136	              "609f6e36d2405585188d5cfd761f407c7cc46a7d3f314c88270469dde315fcd1",
137	          "leaf('abc') = SHA-256(0x00 || 'abc')");
