139	              "54a6dc1bfc990ced3f5757264f357ad708a9ee54ce3d117299641b234f6d5800",
140	          "leaf('hello\\n') includes raw newline byte");
141	
142	    // 叶子不是普通 hash：0x00 前缀必须改变结果。
143	    branchaudit::Sha256 plain;
144	    const unsigned char a_byte = 'a';
145	    plain.update(&a_byte, 1);
146	    const Digest plain_a = plain.final();
147	    check(hex_of(plain_a) ==
