149	          "plain SHA-256('a') reference (no prefix)");
150	    check(leaf_bytes(bytes_of("a")) != plain_a,
151	          "leaf('a') must not equal plain hash('a')");
152	
153	    // 分组/填充边界长度的叶子（前缀使总长度 +1，覆盖各边界）。
154	    struct BCase { std::size_t n; const char* hex; };
155	    const BCase cases[] = {
156	        {55,  "2f96780fb415b287dd95897a04ef96fde6a5f5b0c771d0a1175543bc3250718e"},
157	        {56,  "4632d4b47c0932896996fe232ae65a5af500608fabd0bdbfbb6856795eaf9d85"},
158	        {63,  "5ec0fdb427bf003f71ceb018dfedc0028590a422eaf9f15a69dd1e5a6aa03d5e"},
159	        {64,  "88df0645999a1bc9dec19086e862403750a069436d7ecf7775256f78279b3fcb"},
160	        {65,  "3f104f71a21ddad6e23bac5b43967f5eed6675a5adf0c4050de374fff8055af7"},
161	        {128, "6023f14a3b7582c7e389f4ef3313bc3c6cbf69623e12a7d19485553d02d1f635"},
162	    };
163	    for (const BCase& c : cases) {
164	        check(hex_of(leaf_bytes(fill_a(c.n))) == c.hex,
165	              "leaf of 'a'*" + std::to_string(c.n) + " matches independent value");
166	    }
