187	// ---- 逐文件批次：顺序、重复、奇数提升、路径无关 ---------------------------
188	
189	void test_file_batches() {
190	    TempArea tmp("batches");
191	
192	    const auto empty = bytes_of("");
193	    const auto a = bytes_of("a");
194	    const auto abc = bytes_of("abc");
195	    const auto hello = bytes_of("hello\n");
196	
197	    const fs::path f_empty = tmp.root / "empty.bin";
198	    const fs::path f_a = tmp.root / "a.bin";
199	    const fs::path f_abc = tmp.root / "abc.bin";
200	    const fs::path f_hello = tmp.root / "hello.bin";
201	    write_file(f_empty, empty);
202	    write_file(f_a, a);
203	    write_file(f_abc, abc);
204	    write_file(f_hello, hello);
205	
206	    // 单文件批次：根即叶子摘要。
207	    check(hex_of(root_of({f_a})) == hex_of(leaf_bytes(a)),
208	          "single file: root equals its leaf digest");
209	    check(hex_of(root_of({f_a})) ==
210	              "022a6979e6dab7aa5ae4c3e5e45f7e977112a7e63593820dbec1ec738a24f93c",
211	          "single file root('a') is leaf, not plain hash");
212	    check(hex_of(root_of({f_empty})) ==
213	              "6e340b9cffb37a989ca544e6bb780a2c78901d3fb33738768511a30617afa01d",
214	          "single empty file root differs from empty batch root");
215	
216	    // 两文件、顺序敏感。
217	    check(hex_of(root_of({f_a, f_abc})) ==
218	              "6a5c0676c6dd1efd519348f49315879d99549029726d5dd1a5dedbf700720761",
219	          "root [a, abc]");
220	    check(hex_of(root_of({f_abc, f_a})) ==
221	              "ece02d1ac6ea17f528a19562aea6b77f7e7d1d8224a7583d3fbfc9f6e3d426ab",
222	          "root [abc, a] differs when order is reversed");
223	
224	    // 三文件：末节点原样提升。结构 = parent(parent(La,Lbc), Lempty)。
225	    const Digest p = branchaudit::merkle_parent(leaf_bytes(a), leaf_bytes(abc));
226	    const Digest three = branchaudit::merkle_parent(p, leaf_bytes(empty));
227	    check(hex_of(three) ==
228	              "b3beb69a3342155ac93f8fb124f5b39ec5955cdcbff261495547e03361f9c99a",
229	          "structural 3-file root with odd promotion (independent value)");
230	    check(root_of({f_a, f_abc, f_empty}) == three,
231	          "root [a, abc, empty] matches promoted (not duplicated) structure");
232	
233	    // 明确排除“复制末节点”与“补零”两种错误配对。
234	    const Digest dup_last = branchaudit::merkle_parent(
235	        p, branchaudit::merkle_parent(leaf_bytes(empty), leaf_bytes(empty)));
236	    check(dup_last != three,
237	          "odd node is never duplicated to make a pair");
238	    const Digest zeros{};
239	    check(branchaudit::merkle_parent(p, zeros) != three,
240	          "odd node is never zero-padded to make a pair");
241	
242	    // 不同位置的重复排列给出不同根（不按摘要重排、不去重）。
243	    check(hex_of(root_of({f_a, f_a, f_abc})) ==
244	              "d2b37c5ec897ce0504f95ec7a060d88c38664164a4614b5ca18e5dd3df527702",
245	          "root [a, a, abc] keeps both positions");
246	    check(hex_of(root_of({f_a, f_abc, f_a})) ==
247	              "588340eb2a7896e08c25b9af5be4538358eadeb56e0c685910ac0cc6fb12e006",
248	          "root [a, abc, a] differs from [a, a, abc]");
249	
250	    // 同一路径重复传入，保留两个位置。
251	    check(hex_of(root_of({f_a, f_a})) ==
252	              "8025de747bafe2560d6b991bdb17ca89efe1b6fedda1be209c0ee015338861ea",
253	          "same path twice keeps two positions");
254	    // 两个不同文件、内容相同，结果与重复同一路径一致。
255	    const fs::path f_a_copy = tmp.root / "copy of a.bin";
256	    write_file(f_a_copy, a);
257	    check(root_of({f_a, f_a_copy}) == root_of({f_a, f_a}),
258	          "identical content in distinct files behaves like repeated positions");
259	
260	    // 偶数四文件与奇数五文件（末节点先提升，再与其左侧在上层配对）。
261	    check(hex_of(root_of({f_a, f_abc, f_empty, f_hello})) ==
262	              "ae395b1592efa07192377a24fc187eba186da891a39c12d3dfae9df84f0c9a93",
263	          "root of 4 files");
264	    check(hex_of(root_of({f_a, f_abc, f_empty, f_hello, f_a})) ==
265	              "685686ca622026c4537dfdb49e8f9dac110c553f1d21aee96633e12fa47a7c47",
266	          "root of 5 files (odd promotion across levels)");
267	
268	    // 七文件树：跨层多次奇数提升。
269	    const std::array<std::vector<unsigned char>, 7> seven_data = {
270	        empty, a, bytes_of("bb"), bytes_of("ccc"), bytes_of("dddd"),
271	        bytes_of("eeeee"), bytes_of("ffffff")};
272	    std::array<fs::path, 7> seven;
273	    for (std::size_t i = 0; i < seven.size(); ++i) {
274	        seven[i] = tmp.root / ("seven" + std::to_string(i) + ".bin");
275	        write_file(seven[i], seven_data[i]);
276	    }
277	    check(hex_of(root_of({seven.begin(), seven.end()})) ==
278	              "80bea6847da15bd2a145bbce5c01fb61672c4ad0f91da2e282075758d2610de2",
279	          "root of 7 files (independent multi-level value)");
280	
281	    // 根只反映各位置内容：相同有序内容放在不同路径（含空格/中文目录），
282	    // 根相同。
283	    const fs::path alt_dir = tmp.root / "子 目录" / "另一批";
284	    std::array<fs::path, 3> alt;
285	    alt[0] = alt_dir / "空.bin";
286	    alt[1] = alt_dir / "a file.dat";
287	    alt[2] = tmp.root / "深 路径" / "文 件.bin";
288	    write_file(alt[0], empty);
289	    write_file(alt[1], a);
290	    write_file(alt[2], abc);
291	    const Digest r1 = root_of({f_empty, f_a, f_abc});
292	    const Digest r2 = root_of({alt[0], alt[1], alt[2]});
293	    check(r1 == r2, "root is path-independent: same ordered contents, other paths");
294	    // 顺序不同则根不同，确认不是按路径或摘要排序。
295	    check(root_of({alt[2], alt[1], alt[0]}) != r2,
296	          "different position order yields different root even with same files");
297	}
