318	// ---- 失败：缺失、目录、任一失败即整次失败 ---------------------------------
319	
320	void test_failures() {
321	    TempArea tmp("fail");
322	    const fs::path good1 = tmp.root / "good1.bin";
323	    const fs::path good2 = tmp.root / "good2.bin";
324	    write_file(good1, bytes_of("a"));
325	    write_file(good2, bytes_of("abc"));
326	
327	    const fs::path missing = tmp.root / "does not exist 缺失.bin";
328	    auto names_path = [&](const branchaudit::FileHashResult& r) {
329	        return r.error.find(missing.string()) != std::string::npos;
330	    };
331	
332	    branchaudit::FileHashResult r = branchaudit::merkle_root_files({missing});
333	    check(!r.ok(), "only missing file: batch fails");
334	    check(names_path(r), "missing file: error names the failed path");
335	    check(r.error.size() > missing.string().size() + 2,
336	          "missing file: error gives a reason beyond the path");
337	
338	    // 缺失位于中间：报错指出该路径，而非用其余文件算出结果。
339	    r = branchaudit::merkle_root_files({good1, missing, good2});
340	    check(!r.ok(), "missing file in middle: whole batch fails");
341	    check(names_path(r), "middle failure names the middle path");
342	
343	    // 缺失位于最前。
344	    r = branchaudit::merkle_root_files({missing, good1});
345	    check(!r.ok() && names_path(r), "missing file first: fails on that path");
346	
347	    // 目录不是文件。
348	    const fs::path dir = tmp.root / "a dir 目录";
349	    fs::create_directories(dir);
350	    r = branchaudit::merkle_root_files({good1, dir, good2});
351	    check(!r.ok(), "directory among files: batch fails");
352	    check(r.error.find(dir.string()) != std::string::npos,
353	          "directory: error names the failed path");
354	    check(r.error.find("directory") != std::string::npos,
355	          "directory: error states directory reason");
356	}
