358	// ---- 失败：文件存在却打不开 / 叶子读到一半出错 ----------------------------
359	//
360	// 与“缺失/目录”不同，这两类错误发生在文件真实存在、且读取已经（部分）
361	// 开始之后。经随测试预载的故障注入库在 libc 打开/读取接口确定性触发，
362	// 覆盖普通摘要与文件叶子共用的同一条文件计算路径。
363	
364	void test_io_failures() {
365	    TempArea tmp("iofail");
366	
367	    const fs::path good1 = tmp.root / "good1.bin";
368	    const fs::path good2 = tmp.root / "good2.bin";
369	    const fs::path bad = tmp.root / "present 出错.bin";
370	    const fs::path empty = tmp.root / "empty 空.bin";
371	    constexpr long kPartial = 40;
372	    const auto good_bytes1 = bytes_of("normal-file-one");
373	    const auto good_bytes2 = bytes_of("normal-file-two");
374	    const auto bad_bytes = pattern(200);
375	    write_file(good1, good_bytes1);
376	    write_file(good2, good_bytes2);
377	    write_file(bad, bad_bytes);
378	    write_file(empty, {});
379	
380	    const Digest good_leaf1 = leaf_bytes(good_bytes1);
381	    const Digest good_leaf2 = leaf_bytes(good_bytes2);
382	    const Digest bad_partial_leaf =
383	        branchaudit::merkle_leaf(bad_bytes.data(),
384	                                 static_cast<std::size_t>(kPartial));
385	
386	    // 夹具在无注入时必须成功，排除“写死错误结果”的可能。
387	    check(hex_of(root_of({good1, bad, good2})).size() == 64,
388	          "iofail fixtures: batch succeeds without injected fault");
389	
390	    // ---- 打开失败：唯一位置 --------------------------------------------
391	    {
392	        fault_test::FaultTrigger trigger(
393	            "BRANCHAUDIT_TEST_OPEN_FAIL", bad.string());
394	        branchaudit::FileHashResult r;
395	        auto captured = silent_merkle({bad}, &r);
396	        check(!r.ok(), "unopenable leaf: batch fails");
397	        check(r.error.find(bad.string()) != std::string::npos,
398	              "unopenable leaf: error names the failed file");
399	        check(r.error.find("ermission") != std::string::npos ||
400	                  r.error.find("denied") != std::string::npos ||
401	                  r.error.find("cces") != std::string::npos,
402	              "unopenable leaf: error states open/permission reason");
403	        check(captured.first.empty() && captured.second.empty(),
404	              "unopenable leaf: library prints nothing, does not exit");
405	    }
406	
407	    // ---- 打开失败：有序批次中出错前已经处理过正常文件 ------------------
408	    {
409	        fault_test::FaultTrigger trigger(
410	            "BRANCHAUDIT_TEST_OPEN_FAIL", bad.string());
411	        branchaudit::FileHashResult r;
412	        auto captured = silent_merkle({good1, good2, bad}, &r);
413	        check(!r.ok(),
414	              "open failure after processed good files: whole batch fails");
415	        check(r.error.find(bad.string()) != std::string::npos,
416	              "open failure in batch: error points at the real failing file");
417	        check(r.error.find(good1.string()) == std::string::npos &&
418	                  r.error.find(good2.string()) == std::string::npos,
419	              "open failure in batch: already-processed files are not blamed");
420	        check(captured.first.empty(),
421	              "open failure in batch: no root of the processed prefix is printed");
422	        check(captured.second.empty(),
423	              "open failure in batch: library prints nothing");
424	        // 不得给出“仅前两个正常文件”的根。
425	        check(r.digest != branchaudit::merkle_parent(good_leaf1, good_leaf2),
426	              "open failure: root skipping the failing position is not returned");
427	        check(r.digest != good_leaf1,
428	              "open failure: a processed leaf is not returned as the root");
429	    }
430	
431	    // ---- 读取失败：叶子取得部分内容后继续读出错 ------------------------
432	    {
433	        fault_test::FaultTrigger trigger(
434	            "BRANCHAUDIT_TEST_READ_FAIL",
435	            bad.string() + ":" + std::to_string(kPartial));
436	        branchaudit::FileHashResult r;
437	        auto captured = silent_merkle({bad}, &r);
438	        check(!r.ok(), "read error mid-leaf: batch fails");
439	        check(r.error.find(bad.string()) != std::string::npos,
440	              "read failure: error names the failed file");
441	        check(r.error.find("read") != std::string::npos,
442	              "read failure: error says read failed rather than normal EOF");
443	        check(captured.first.empty() && captured.second.empty(),
444	              "read failure: library prints nothing");
445	        // 已读到的部分内容不能成为成功叶子摘要。
446	        check(r.digest != bad_partial_leaf,
447	              "read failure: partial leaf digest is not returned as success");
448	        check(r.digest != leaf_bytes(bad_bytes),
449	              "read failure: full-content leaf is not fabricated either");
450	    }
451	
452	    // ---- 读取失败：出错前正常文件已处理，仍整次失败且指向真正出错文件 --
453	    {
454	        fault_test::FaultTrigger trigger(
455	            "BRANCHAUDIT_TEST_READ_FAIL",
456	            bad.string() + ":" + std::to_string(kPartial));
457	        branchaudit::FileHashResult r;
458	        auto captured = silent_merkle({good1, bad, good2}, &r);
459	        check(!r.ok(),
460	              "read error after a good file: whole ordered batch fails");
461	        check(r.error.find(bad.string()) != std::string::npos,
462	              "batch read failure: error names the truly failing file");
463	        check(r.error.find(good1.string()) == std::string::npos &&
464	                  r.error.find(good2.string()) == std::string::npos,
465	              "batch read failure: good files are not named as the cause");
466	        check(captured.first.empty(),
467	              "batch read failure: no partial/skipped-position root is emitted");
468	        check(captured.second.empty(),
469	              "batch read failure: library prints nothing");
470	        check(r.digest != good_leaf1,
471	              "batch read failure: processed-prefix leaf is not a result");
472	    }
473	
474	    // ---- 空文件叶子在读取故障武装下仍正常读完 --------------------------
475	    {
476	        fault_test::FaultTrigger trigger(
477	            "BRANCHAUDIT_TEST_READ_FAIL",
478	            empty.string() + ":" + std::to_string(kPartial));
479	        branchaudit::FileHashResult r;
480	        auto captured = silent_merkle({empty}, &r);
481	        check(r.ok(),
482	              "empty file leaf reads to completion successfully (no content != error)");
483	        check(hex_of(r.digest) ==
484	                  "6e340b9cffb37a989ca544e6bb780a2c78901d3fb33738768511a30617afa01d",
485	              "empty file leaf remains SHA-256(0x00)");
486	        check(captured.first.empty() && captured.second.empty(),
487	              "empty file leaf: library prints nothing");
488	    }
489	
490	    // ---- 故障只作用于指定路径：批次中其他文件不受影响 ------------------
491	    {
492	        fault_test::FaultTrigger trigger(
493	            "BRANCHAUDIT_TEST_READ_FAIL",
494	            bad.string() + ":" + std::to_string(kPartial));
495	        branchaudit::FileHashResult r;
496	        silent_merkle({good1, good2}, &r);
497	        check(r.ok() && r.digest == branchaudit::merkle_parent(good_leaf1, good_leaf2),
498	              "fault is path-scoped: batch without the named path is unaffected");
499	    }
500	}
501	
502	// ---- 大文件：流式读取、尾部敏感 -------------------------------------------
503	
504	void test_large_files() {
505	    TempArea tmp("large");
506	    const std::vector<unsigned char> big = fill_a(200000);
507	    const std::vector<unsigned char> pat = pattern(200000);
508	    const fs::path f_big = tmp.root / "a200000.bin";
509	    const fs::path f_pat = tmp.root / "pattern200000.bin";
510	    write_file(f_big, big);
511	    write_file(f_pat, pat);
512	
513	    check(hex_of(root_of({f_big})) ==
514	              "0ce74c178a2d90235341a8a2e17539e34aad75dfead1f361b5bec500c1eff93e",
515	          "single large file leaf (streaming)");
516	    check(hex_of(root_of({f_big, f_pat})) ==
517	              "a801ef6c29a4ee3e4e2bc339c7437fe24a2bc10b86571825062a80f6a374daa0",
518	          "root [big, pattern]");
519	    check(hex_of(root_of({f_pat, f_big})) ==
520	              "892596758489f559ec8778ed1d271cd52b18a340926ef47cd16481a432bf2494",
521	          "root [pattern, big] differs under reversal");
522	
523	    // 仅最后一个字节不同：叶子必须随之改变（流式尾部不遗漏）。
524	    std::vector<unsigned char> tail = big;
525	    tail.back() = static_cast<unsigned char>('b');
526	    const fs::path f_tail = tmp.root / "a200000tail.bin";
527	    write_file(f_tail, tail);
528	    check(hex_of(root_of({f_tail})) ==
529	              "e705589769e167619ac6a979e5e06f245ff1ff34a65f34e261b728abc4698a75",
530	          "large file: changing last byte changes leaf/root");
531	    check(root_of({f_tail}) != root_of({f_big}),
532	          "large file: tail change is detected");
533	}
534	
535	}  // namespace
536	
537	int main(int argc, char** argv) {
538	    fault_test::ensure_fault_preloaded(argc, argv);
539	
540	    test_empty_batch();
541	    test_leaf_rule();
542	    test_parent_rule();
543	    test_file_batches();
544	    test_relative_paths();
545	    test_failures();
546	    test_io_failures();
547	    test_large_files();
548	
549	    if (g_failures == 0) {
550	        std::cout << "all " << g_checks << " merkle regression checks passed\n";
551	        return 0;
552	    }
553	    std::cerr << g_failures << " of " << g_checks << " checks failed\n";
554	    return 1;
555	}
